/**
 * @summary Get one book order with its items and shipments
 */
export const BookOrdersControllerFindByIdParams = zod.object({
  orderId: zod.uuid().describe("Order id"),
});

export const BookOrdersControllerFindByIdResponse = zod.object({
  createdAt: zod.string(),
  currency: zod
    .union([zod.literal("UAH"), zod.literal("EUR"), zod.literal("USD"), zod.literal(null)])
    .nullable(),
  deliveryPrice: zod.number().nullable(),
  derivedStatus: zod.enum([
    "active",
    "partially_shipped",
    "shipped",
    "partially_received",
    "received",
    "cancelled",
  ]),
  discount: zod.number().nullable(),
  id: zod.string(),
  isFree: zod
    .boolean()
    .describe("The order was received for free, so its canonical total is zero."),
  items: zod.array(
    zod.object({
      bookId: zod.string(),
      cancelledAt: zod.string().nullable(),
      cancelReason: zod.string().nullable(),
      id: zod.string(),
      orderId: zod.string(),
      price: zod.number().nullable(),
      receivedAt: zod.string().nullable(),
      shipmentId: zod.string().nullable(),
    }),
  ),
  note: zod.string().nullable(),
  orderDate: zod.string().nullable(),
  orderNumber: zod.string().nullable(),
  shipments: zod.array(
    zod.object({
      cancelledAt: zod.string().nullable(),
      cancelReason: zod.string().nullable(),
      createdAt: zod.string(),
      deliveryService: zod
        .object({
          id: zod.string().nullable(),
          name: zod.string(),
        })
        .nullable(),
      expectedDeliveryDate: zod.string().nullable(),
      id: zod.string(),
      note: zod.string().nullable(),
      orderId: zod.string(),
      pickupUntil: zod.string().nullable(),
      receivedAt: zod.string().nullable(),
      status: zod.enum(["ordered", "in_transit", "ready_for_pickup", "received", "cancelled"]),
      trackingNumber: zod.string().nullable(),
      trackingUrl: zod.string().nullable(),
      updatedAt: zod.string(),
    }),
  ),
  storeName: zod.string(),
  totalAmount: zod.number().nullable(),
  updatedAt: zod.string(),
});

/**
 * @summary Edit the order-level fields of a book order
 */
export const BookOrdersControllerUpdateParams = zod.object({
  orderId: zod.uuid().describe("Order id"),
});

export const bookOrdersControllerUpdateBodyDeliveryPriceMin = 0;
export const bookOrdersControllerUpdateBodyDeliveryPriceMax = 99999999.99;

export const bookOrdersControllerUpdateBodyDiscountMin = 0;
export const bookOrdersControllerUpdateBodyDiscountMax = 99999999.99;

export const bookOrdersControllerUpdateBodyOrderDateRegExp = new RegExp(
  "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$",
);
export const bookOrdersControllerUpdateBodyTotalAmountMin = 0;
export const bookOrdersControllerUpdateBodyTotalAmountMax = 99999999.99;

export const BookOrdersControllerUpdateBody = zod.object({
  currency: zod.enum(["UAH", "EUR", "USD"]).optional(),
  deliveryPrice: zod
    .number()
    .min(bookOrdersControllerUpdateBodyDeliveryPriceMin)
    .max(bookOrdersControllerUpdateBodyDeliveryPriceMax)
    .nullish(),
  discount: zod
    .number()
    .min(bookOrdersControllerUpdateBodyDiscountMin)
    .max(bookOrdersControllerUpdateBodyDiscountMax)
    .nullish(),
  isFree: zod.boolean().optional(),
  note: zod.string().nullish(),
  orderDate: zod.iso.date().regex(bookOrdersControllerUpdateBodyOrderDateRegExp).nullish(),
  orderNumber: zod.string().nullish(),
  storeName: zod.string().optional(),
  totalAmount: zod
    .number()
    .min(bookOrdersControllerUpdateBodyTotalAmountMin)
    .max(bookOrdersControllerUpdateBodyTotalAmountMax)
    .nullish(),
});

